void  npc_reset( Npc npc )
{	
	vrtc_stop( (Vrtc)npc );
 	
	vrtc_update( (Vrtc)npc , npc->timeout );

	npc->count = 0 ; 
	
	npc->is_active = FALSE ; 
	
	npc->is_enable = FALSE ;	
}
